/*
 * dir_$write_def_prot - store one default protection in a directory's
 * root page
 *
 * Original address: 0x00E51E18
 * Size: 552 bytes (0x00E51E18 .. 0x00E5203F)
 * Generated by: Claude Opus 5.5
 *
 * Module-local routine of the DIR segment (no map symbol); its one caller
 * is dir_$do_op_set_def_prot (0x00E52086), with flush_flag 0xFF.
 *
 * Frame: (0x8,A6) handle (D4), (0xC,A6) acl_type (D5), (0x10,A6)
 * prot_data, (0x14,A6) src_acl_uid (A2), (0x18,A6) flush_flag byte (D3b,
 * the high byte of its word slot), (0x1A,A6) status_ret (A3).  Locals:
 * A6-0xA0 the 11-longword protection block, A6-0x70 the new ACL UID,
 * A6-0x68 the old one, A6-0x60 CONVERT_FUNKY_ACL's type UID, A6-0x58 the
 * location record, A6-0x38 the attribute word, A6-0xA8/-0xAC
 * AST_$GET_LOCATION's outputs, A6-0xB0 a private status, A6-0xB2
 * AST_$TRUNCATE's boolean.
 *
 * Blocks:
 *   0x00E51E34-0x00E51E40  *status_ret = ok; A4 = dir_$map_page(handle, 0)
 *   0x00E51E42-0x00E51E7A  src_acl_uid in a "funky" encoding (bits 4..11 of
 *                          its low half's high word, masked 0xE0):
 *                          ACL_$CONVERT_FUNKY_ACL(src, prot, &new_uid,
 *                          &type_uid, status_ret); error -> exit; clear bit
 *                          24 of new_uid.low (`bclr.b #0,(-0x6c,A6)')
 *   0x00E51E7C-0x00E51E92  otherwise prot = the 11 longwords at prot_data,
 *                          new_uid = *src_acl_uid
 *   0x00E51E96-0x00E51F04  D2 = new_uid's first byte; non-zero: the ACL
 *                          object must be local and on the directory's
 *                          volume: AST_$GET_LOCATION(&loc, 1, ...) ok,
 *                          handle->volume == loc.volume, loc.flags bit 7
 *                          clear.  Otherwise *status_ret = the private
 *                          status, and ok or file_$object_not_found become
 *                          file_$objects_on_different_volumes; exit
 *   0x00E51F08-0x00E51F26  ACL_$SET_DEF_ACL_CHECK(handle, prot, &new_uid,
 *                          &DIR_$CONST_FOUR_W, acl_type, status_ret) false
 *                          -> exit
 *   0x00E51F2A-0x00E51F78  ACL_$DIR_ACL: old_uid = page+0x46; page+0x1A =
 *                          prot; same UID -> 0x00E52020, else page+0x46 =
 *                          new_uid
 *   0x00E51F7A-0x00E51FC6  ACL_$FILE_ACL: the same with page+0x7A / +0x4E
 *   0x00E51FC8             any other type: status_$naming_bad_type, exit
 *   0x00E51FD0-0x00E51FF6  D2 != 0: AST_$SET_ATTRIBUTE(&new_uid, 6, &1,
 *                          status_ret); error -> exit
 *   0x00E51FF8-0x00E5201C  old_uid's first byte != 0:
 *                          AST_$TRUNCATE(&old_uid, 0, 3, &b, &private)
 *   0x00E52020-0x00E52030  flush_flag < 0: FILE_$FW_PARTIAL(handle,
 *                          &DIR_$CONST_ZERO_L, &DIR_$ONE_PAGE_L, status_ret)
 *
 * Quirks reproduced:
 *   - An unchanged ACL UID skips the attribute and truncate steps but still
 *     reaches the flush (`beq.w 0x00e52020').
 *   - The two AST_$SET_ATTRIBUTE / AST_$GET_LOCATION calls reserve a Pascal
 *     result word nobody reads; AST_$TRUNCATE's status goes to the private
 *     cell and is not looked at.
 */

#include "dir/dir_internal.h"

/* `move.w #0x1,-(SP)' 0x00E51EC0: AST_$GET_LOCATION's flags */
#define WRITE_DEF_PROT_LOC_FLAGS        1
/* `move.w #0x6,-(SP)' 0x00E51FE2: attribute 6 raises the reference count */
#define WRITE_DEF_PROT_ATTR_REFCNT      6
/* `move.w #0x3,-(SP)' 0x00E5200C: AST_$TRUNCATE's flags */
#define WRITE_DEF_PROT_TRUNC_FLAGS      3

void dir_$write_def_prot(uint32_t handle, uid_t *acl_type,
                         uint32_t *prot_data, uid_t *src_acl_uid,
                         int8_t flush_flag, status_$t *status_ret)
{
    dir_$handle_t *h = (dir_$handle_t *)ARCH_VA_TO_PTR(handle);  /* D4 */
    uint8_t *page;                          /* A4 */
    dir_$def_prot_t *slot;
    uint32_t prot[DIR_DEF_PROT_LONGS];      /* A6-0xA0 */
    uid_t new_uid;                          /* A6-0x70 */
    uid_t old_uid;                          /* A6-0x68 */
    uid_t type_uid;                         /* A6-0x60 */
    file_$obj_loc_t loc;                    /* A6-0x58 */
    uint16_t attr_val;                      /* A6-0x38 */
    uint32_t loc_unused;                    /* A6-0xA8 */
    uint32_t loc_out;                       /* A6-0xAC */
    status_$t status;                       /* A6-0xB0 */
    boolean trunc_result;                   /* A6-0xB2 */
    uint16_t first_byte;                    /* D2 */
    int16_t i;

    /* 0x00E51E34-0x00E51E40 */
    *status_ret = status_$ok;
    page = (uint8_t *)dir_$map_page(h, 0);

    if (((((uint16_t)(src_acl_uid->low >> 16)) & 0xFF0) >> 4 & 0xE0) != 0) {
        /* 0x00E51E54-0x00E51E7A */
        ACL_$CONVERT_FUNKY_ACL(src_acl_uid, prot, &new_uid, &type_uid,
                               status_ret);
        if (*status_ret != status_$ok) {
            return;
        }
        new_uid.low &= ~0x01000000u;
    } else {
        /* 0x00E51E7C-0x00E51E92 */
        for (i = 0; i < DIR_DEF_PROT_LONGS; i++) {  /* dbf #0xA */
            prot[i] = prot_data[i];
        }
        new_uid.high = src_acl_uid->high;
        new_uid.low = src_acl_uid->low;
    }

    /* 0x00E51E96-0x00E51F04 */
    first_byte = (uint16_t)(new_uid.high >> 24);
    if (first_byte != 0) {
        loc.uid.high = new_uid.high;
        loc.uid.low = new_uid.low;
        loc.flags &= (int8_t)~FILE_OBJ_LOC_SCRATCH;
        AST_$GET_LOCATION(&loc, WRITE_DEF_PROT_LOC_FLAGS, &loc_unused,
                          &loc_out, &status);
        if (status != status_$ok || h->volume != (int16_t)loc.volume ||
            loc.flags < 0) {
            *status_ret = status;
            if (*status_ret == file_$object_not_found ||
                *status_ret == status_$ok) {
                *status_ret = file_$objects_on_different_volumes;
            }
            return;
        }
    }

    /* 0x00E51F08-0x00E51F26 */
    if (ACL_$SET_DEF_ACL_CHECK(&h->uid, prot, &new_uid, &DIR_$CONST_FOUR_W,
                               acl_type, status_ret) >= 0) {
        return;
    }

    if (acl_type->high == ACL_$DIR_ACL.high &&
        acl_type->low == ACL_$DIR_ACL.low) {
        /* 0x00E51F3C-0x00E51F78 */
        slot = (dir_$def_prot_t *)(page + DIR_ROOT_DIR_DEF_PROT);
    } else if (acl_type->high == ACL_$FILE_ACL.high &&
               acl_type->low == ACL_$FILE_ACL.low) {
        /* 0x00E51F8C-0x00E51FC6 */
        slot = (dir_$def_prot_t *)(page + DIR_ROOT_FILE_DEF_PROT);
    } else {
        /* 0x00E51FC8 */
        *status_ret = status_$naming_bad_type;
        return;
    }

    old_uid.high = slot->acl_uid.high;
    old_uid.low = slot->acl_uid.low;
    for (i = 0; i < DIR_DEF_PROT_LONGS; i++) {  /* dbf #0xA */
        slot->prot[i] = prot[i];
    }

    if (new_uid.high != old_uid.high || new_uid.low != old_uid.low) {
        slot->acl_uid.high = new_uid.high;
        slot->acl_uid.low = new_uid.low;

        /* 0x00E51FD0-0x00E51FF6 */
        if (first_byte != 0) {
            attr_val = 1;
            AST_$SET_ATTRIBUTE(&new_uid, WRITE_DEF_PROT_ATTR_REFCNT,
                               &attr_val, status_ret);
            if (*status_ret != status_$ok) {
                return;
            }
        }

        /* 0x00E51FF8-0x00E5201C */
        if ((uint8_t)(old_uid.high >> 24) != 0) {
            AST_$TRUNCATE(&old_uid, 0, WRITE_DEF_PROT_TRUNC_FLAGS,
                          &trunc_result, &status);
        }
    }

    /* 0x00E52020-0x00E52030 */
    if (flush_flag < 0) {
        FILE_$FW_PARTIAL(&h->uid, &DIR_$CONST_ZERO_L,
                         (uint32_t *)&DIR_$ONE_PAGE_L, status_ret);
    }
}
